// frontend/src/components/Collaboration.jsx
import React, { useEffect, useRef, useState } from "react";
import { io } from "socket.io-client";

const BASE_URL = "http://127.0.0.1:8000";

export default function Collaboration() {
  const [room, setRoom] = useState("");
  const [status, setStatus] = useState("connecting...");
  const [code, setCode] = useState("");
  const [comments, setComments] = useState([]);
  const [commentInput, setCommentInput] = useState("");
  const [socket, setSocket] = useState(null);

  // refs used for patch diffing and to avoid re-applying local changes
  const lastTextRef = useRef("");
  const applyingRemotePatch = useRef(false);
  const socketRef = useRef(null);

  // Read room code from URL on mount
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const r = params.get("room") || params.get("code") || "DEMO123";
    setRoom(r);
  }, []);

  // Init socket and handlers
  useEffect(() => {
    if (!room) return;

    const s = io(BASE_URL, { transports: ["websocket"] });
    socketRef.current = s;
    setSocket(s);

    s.on("connect", () => {
      setStatus("connected");
      // join requested room
      s.emit("join", { room });
    });

    s.on("disconnect", () => {
      setStatus("disconnected");
    });

    // initial full document (sent only to this client)
    s.on("editor_full", (msg) => {
      const content = msg?.content || "";
      lastTextRef.current = content;
      setCode(content);
    });

    // incoming patch to apply
    s.on("editor_update", (patch) => {
      // patch: { start, removedLength, text }
      if (!patch || typeof patch.start !== "number") return;

      applyingRemotePatch.current = true;

      setCode((prev) => {
        const before = prev.slice(0, patch.start);
        const after = prev.slice(patch.start + (patch.removedLength || 0));
        const updated = before + (patch.text || "") + after;
        lastTextRef.current = updated;
        return updated;
      });

      // small timeout to re-enable local edits
      setTimeout(() => (applyingRemotePatch.current = false), 0);
    });

    // comment history (sent to this SID)
    s.on("room_history", (docs) => {
      if (Array.isArray(docs)) {
        setComments(docs);
      }
    });

    // new comment broadcast
    s.on("new_comment", (doc) => {
      if (!doc) return;
      setComments((prev) => {
        // avoid duplicates if we optimistically added same id
        if (prev.some((c) => c._id === doc._id || c.id === doc.id)) return prev;
        return [...prev, doc];
      });
    });

    // cleanup on unmount
    return () => {
      try {
        s.close();
      } catch (e) {}
    };
  }, [room]);

  // compute patch (start index, removedLength, addedText)
  function computePatch(oldText, newText) {
    if (oldText === newText) return null;

    let start = 0;
    const minLen = Math.min(oldText.length, newText.length);
    while (start < minLen && oldText[start] === newText[start]) start++;

    let endOld = oldText.length;
    let endNew = newText.length;
    while (endOld > start && endNew > start && oldText[endOld - 1] === newText[endNew - 1]) {
      endOld--;
      endNew--;
    }

    const removedLength = endOld - start;
    const addedText = newText.slice(start, endNew);

    return { start, removedLength, text: addedText };
  }

  // handle local editor changes
  const onCodeChange = (e) => {
    const newText = e.target.value;

    // if we're applying remote patch, skip sending back
    if (applyingRemotePatch.current) {
      lastTextRef.current = newText;
      setCode(newText);
      return;
    }

    const oldText = lastTextRef.current;
    const patch = computePatch(oldText, newText);

    // update local immediately
    lastTextRef.current = newText;
    setCode(newText);

    if (!patch) return;

    // send patch via socket (backend expects removedLength key name)
    if (socketRef.current && socketRef.current.connected) {
      socketRef.current.emit("editor_broadcast", {
        room,
        start: patch.start,
        removedLength: patch.removedLength,
        text: patch.text,
      });
    }
  };

  // send comment (optimistic append)
  const sendComment = () => {
    const text = commentInput.trim();
    if (!text || !socketRef.current || !socketRef.current.connected) return;

    // create optimistic comment object (temporary id)
    const optimistic = {
      id: `tmp-${Date.now()}`,
      author: "You",
      text,
      timestamp: new Date().toLocaleString(),
      pending: true,
    };

    setComments((prev) => [...prev, optimistic]);
    setCommentInput("");

    socketRef.current.emit(
      "comment",
      { room, author: "You", text },
      // optional ack callback (some backends support)
      (ack) => {
        // if backend provides ack, we could replace optimistic with real doc
      }
    );
  };

  // keyboard shortcut: Ctrl/Cmd + Enter to send comment
  useEffect(() => {
    const handler = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
        // focus was probably in editor or comment input — send comment only if comment input has value
        if (document.activeElement && document.activeElement.tagName === "INPUT") {
          sendComment();
        }
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [commentInput]);

  // small helper to format comment UI (replaces optimistic when backend emits actual comment)
  useEffect(() => {
    // whenever comments update, if there are temporary items older than 30s, drop pending flag
    const t = setTimeout(() => {
      setComments((prev) =>
        prev.map((c) => {
          if (c.pending && Date.now() - (parseInt(c.id.split("-")[1] || "0") || 0) > 30000) {
            return { ...c, pending: false };
          }
          return c;
        })
      );
    }, 5000);
    return () => clearTimeout(t);
  }, [comments]);

  // UI styles (inline but organized)
  const styles = {
    page: {
      minHeight: "100vh",
      padding: 28,
      background:
        "linear-gradient(180deg, rgba(16,18,23,1) 0%, rgba(20,21,26,1) 100%)",
      fontFamily: "'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial",
      color: "#e6eef8",
      display: "flex",
      justifyContent: "center",
    },
    card: {
      width: "100%",
      maxWidth: 1400,
      borderRadius: 14,
      overflow: "hidden",
      boxShadow: "0 12px 40px rgba(2,6,23,0.7)",
      border: "1px solid rgba(255,255,255,0.04)",
    },
    header: {
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      padding: "20px 28px",
      background: "linear-gradient(90deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01))",
      borderBottom: "1px solid rgba(255,255,255,0.02)",
      backdropFilter: "blur(6px)",
    },
    titleBlock: {
      display: "flex",
      flexDirection: "column",
    },
    title: {
      margin: 0,
      fontSize: 20,
      fontWeight: 700,
      letterSpacing: "-0.2px",
      color: "#ffffff",
    },
    subtitle: {
      marginTop: 6,
      color: "rgba(230,238,248,0.65)",
      fontSize: 13,
    },
    mainGrid: {
      display: "grid",
      gridTemplateColumns: "1fr 380px",
      minHeight: 560,
      background: "#0b0c10",
    },
    editorPanel: {
      display: "flex",
      flexDirection: "column",
      borderRight: "1px solid rgba(255,255,255,0.03)",
      background:
        "linear-gradient(180deg, rgba(10,11,14,0.6), rgba(6,7,9,0.6))",
    },
    editorBar: {
      padding: "14px 18px",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      borderBottom: "1px solid rgba(255,255,255,0.02)",
      background: "rgba(255,255,255,0.01)",
    },
    editorTitle: {
      margin: 0,
      color: "#fff",
      fontSize: 14,
      fontWeight: 700,
    },
    textarea: {
      flex: 1,
      width: "100%",
      padding: 22,
      background: "transparent",
      color: "#e6eef8",
      border: "none",
      resize: "none",
      outline: "none",
      fontSize: 14,
      lineHeight: 1.7,
      fontFamily: "Fira Code, 'Courier New', monospace",
    },
    commentPanel: {
      display: "flex",
      flexDirection: "column",
      background: "linear-gradient(180deg, rgba(7,9,12,0.7), rgba(6,7,9,0.7))",
    },
    commentHeader: {
      padding: "16px 18px",
      borderBottom: "1px solid rgba(255,255,255,0.02)",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      background: "rgba(255,255,255,0.01)",
    },
    commentList: {
      padding: 18,
      overflowY: "auto",
      flex: 1,
    },
    commentBox: {
      marginBottom: 12,
      padding: "10px 12px",
      borderRadius: 10,
      background: "linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01))",
      border: "1px solid rgba(255,255,255,0.02)",
    },
    commentMeta: {
      display: "flex",
      justifyContent: "space-between",
      marginBottom: 6,
      fontSize: 12,
      color: "rgba(230,238,248,0.7)",
    },
    commentText: {
      fontSize: 14,
      color: "rgba(230,238,248,0.95)",
      margin: 0,
      whiteSpace: "pre-wrap",
    },
    commentInputWrap: {
      padding: 14,
      borderTop: "1px solid rgba(255,255,255,0.02)",
      display: "flex",
      gap: 10,
      alignItems: "center",
      background: "rgba(255,255,255,0.01)",
    },
    input: {
      flex: 1,
      padding: "10px 12px",
      background: "rgba(0,0,0,0.45)",
      color: "#e6eef8",
      border: "1px solid rgba(255,255,255,0.02)",
      borderRadius: 10,
      outline: "none",
      fontSize: 13,
    },
    sendButton: {
      padding: "10px 14px",
      background:
        "linear-gradient(180deg, rgba(103,126,234,1), rgba(118,76,178,1))",
      border: "none",
      color: "#fff",
      fontWeight: 700,
      borderRadius: 10,
      cursor: "pointer",
    },
    footer: {
      padding: "12px 18px",
      borderTop: "1px solid rgba(255,255,255,0.02)",
      fontSize: 13,
      color: "rgba(230,238,248,0.6)",
      background: "rgba(255,255,255,0.01)",
    },
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <div style={styles.header}>
          <div style={styles.titleBlock}>
            <h2 style={styles.title}>👥 GPT Collaboration Studio</h2>
            <div style={styles.subtitle}>
              Room <strong style={{ fontFamily: "monospace", marginLeft: 8 }}>{room}</strong>
            </div>
          </div>

          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            <button
              onClick={() => (window.location.href = "/lobby?room=" + encodeURIComponent(room))}
              style={{
                padding: "9px 12px",
                borderRadius: 10,
                background: "transparent",
                border: "1px solid rgba(255,255,255,0.04)",
                color: "#e6eef8",
                cursor: "pointer",
              }}
            >
              ← Back
            </button>

            <div
              style={{
                padding: "8px 12px",
                borderRadius: 10,
                background: status === "connected" ? "rgba(74,222,128,0.12)" : "rgba(250,204,21,0.06)",
                border: "1px solid rgba(255,255,255,0.02)",
                color: status === "connected" ? "#4ade80" : "#fbbf24",
                fontWeight: 700,
                fontSize: 13,
              }}
            >
              {status === "connected" ? "Connected" : "Connecting..."}
            </div>
          </div>
        </div>

        <div style={styles.mainGrid}>
          {/* Editor Panel */}
          <div style={styles.editorPanel}>
            <div style={styles.editorBar}>
              <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
                <div style={{ width: 10, height: 10, borderRadius: 3, background: "#ff5e62" }} />
                <div style={{ width: 10, height: 10, borderRadius: 3, background: "#ffb86b" }} />
                <div style={{ width: 10, height: 10, borderRadius: 3, background: "#8be9fd" }} />
                <h4 style={{ margin: 0, marginLeft: 8, color: "#cfe3ff" }}>Live Editor</h4>
              </div>
              <div style={{ color: "rgba(230,238,248,0.6)", fontSize: 13 }}>
                {code.split("\n").length} lines • {code.length} chars
              </div>
            </div>

            <textarea
              value={code}
              onChange={onCodeChange}
              placeholder="// Start coding — changes sync to everyone in the room"
              style={styles.textarea}
            />
          </div>

          {/* Comments Panel */}
          <div style={styles.commentPanel}>
            <div style={styles.commentHeader}>
              <div style={{ display: "flex", flexDirection: "column" }}>
                <div style={{ fontWeight: 700, color: "#fff" }}>💬 Discussion</div>
                <div style={{ fontSize: 12, color: "rgba(230,238,248,0.55)" }}>
                  Collaborators can comment on lines and suggestions
                </div>
              </div>
            </div>

            <div style={styles.commentList} id="comment-list">
              {comments.length === 0 ? (
                <div style={{ textAlign: "center", color: "rgba(230,238,248,0.28)", marginTop: 40 }}>
                  <div style={{ fontSize: 42 }}>💡</div>
                  <div style={{ marginTop: 8, fontSize: 14 }}>No comments yet — add the first one</div>
                </div>
              ) : (
                comments.map((c, i) => (
                  <div key={c._id || c.id || i} style={styles.commentBox}>
                    <div style={styles.commentMeta}>
                      <div style={{ fontWeight: 700, color: "#fff" }}>{c.author || c.user || "User"}</div>
                      <div style={{ color: "rgba(230,238,248,0.45)" }}>{c.timestamp || (new Date().toLocaleTimeString())}</div>
                    </div>
                    <p style={styles.commentText}>{c.text}</p>
                    {c.pending && <div style={{ fontSize: 12, color: "rgba(230,238,248,0.45)", marginTop: 8 }}>Sending…</div>}
                  </div>
                ))
              )}
            </div>

            <div style={styles.commentInputWrap}>
              <input
                value={commentInput}
                onChange={(e) => setCommentInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && sendComment()}
                placeholder="Write a comment and press Enter"
                style={styles.input}
              />
              <button onClick={sendComment} style={styles.sendButton}>
                Send
              </button>
            </div>
          </div>
        </div>

        <div style={styles.footer}>
          Pro tip: Use <strong>Ctrl/Cmd + Enter</strong> in the comment input to send quickly.
        </div>
      </div>
    </div>
  );
}
